# Test to find pets by tags
@pytest.mark.parametrize(
    "tags, expected_status",
    [
        (["dog", "cat"], 200),              # Valid tags, expect success
        (["invalid_tag"], 400),            # Invalid tags, expect client error
        ([], 200),                         # Empty/None tags, expect success
    ]
)
def test_find_by_tags(base_url, auth_headers, tags, expected_status):
    """
    Test /pet/findByTags endpoint with various tag combinations.
    """
    endpoint = f"{base_url}/pet/findByTags"
    params = {"tags": tags} if tags else None
    response = requests.get(endpoint, headers=auth_headers, params=params)
    
    assert response.status_code == expected_status
    
    if response.status_code == 200:
        # Validate response JSON schema
        pets = response.json()
        assert isinstance(pets, list)
        
        for pet in pets:
            assert "name" in pet
            assert "photoUrls" in pet
            
            if "category" in pet:
                category = pet["category"]
                assert "id" in category
                assert "name" in category
        
            if "tags" in pet:
                for tag in pet["tags"]:
                    assert "id" in tag
                    assert "name" in tag

